// Labelled fixtures for the organizational query-scoring rules.
//
// A rubric nobody can reproduce is a rubric nobody can dispute, so every case
// this module scores has a fixture here with a *stated expectation* beside it:
// what the sample is, why it exists, and what the scorer must say about it. The
// suite iterates this table, so adding a case is adding a row rather than
// writing a new assertion, and a weight change moves the expectation and the
// assertion in the same commit.
//
// Every fixture is generated by a pure function of an index — no clock, no
// randomness, no committed 60-row dump — so a reader can read the generator in
// one screen and know exactly what the bytes are. Nothing here is a vendor
// export, a customer record, or real prompt text: unit keys are `psn_`-shaped
// pseudonyms of nothing, model names are of a vendor that does not exist, and
// the four excerpts are the shortest strings that trip one classifier rule each.
//
// The one fixture that is not generated is the registry's own bundled sample,
// `contracts/integrations/org-query-source/v1/fixtures/organizational-sample.json`.
// It is named here as a case so the table covers it, and the suite reads it off
// disk rather than this module opening a file: nothing in `src/` performs I/O.

/** The two pseudonymous units every generated fixture attributes to. */
export const FIXTURE_UNITS = Object.freeze([
  "psn_unit_fixture_alpha_0001",
  "psn_unit_fixture_bravo_0002",
]);

const MODELS = Object.freeze(["acme-sonnet-1", "acme-haiku-1", "acme-opus-1"]);
const CATEGORY_CYCLE = Object.freeze([
  "highValue", "inefficient", "overProvisioned", "highValue", "outOfScope", "highValue",
]);

/**
 * The four excerpts, one per outcome the classifier can reach.
 *
 * Each is the shortest phrase that matches exactly one rule in
 * `query-classification.js`, so its confidence is 1.0 and the fixture tests the
 * *plumbing* rather than the classifier's tie-breaks — those have their own
 * suite. `ambiguous` matches no rule at all, which is the honest name for it:
 * the classifier will not place it, and the scorer must count it rather than
 * guess.
 */
export const FIXTURE_EXCERPTS = Object.freeze({
  highValue: "context: the deploy log below",
  inefficient: "try again",
  outOfScope: "share a recipe for banana bread",
  ambiguous: "hello there",
});

const pad = (value) => String(value).padStart(2, "0");

/** Day buckets that step one calendar day at a time inside one UTC month. */
function dayBucket(index) {
  return `2026-06-${pad((index % 28) + 1)}`;
}

/**
 * `count` records across the two units, categories cycling, one day bucket per
 * pair. `excerptKey` swaps the declared category for an excerpt, which is how
 * the redaction cases are built: the same shape, with prompt text in it.
 */
export function fixtureRecords({ count = 60, excerptKey = null } = {}) {
  return Array.from({ length: count }, (unused, index) => {
    const record = {
      org_unit_id: FIXTURE_UNITS[index % FIXTURE_UNITS.length],
      query_date: dayBucket(Math.floor(index / FIXTURE_UNITS.length)),
      model_raw: MODELS[index % MODELS.length],
      input_tokens: 400 + index,
      output_tokens: 120 + index,
    };
    if (excerptKey) record.prompt_excerpt = FIXTURE_EXCERPTS[excerptKey];
    else record.category = CATEGORY_CYCLE[index % CATEGORY_CYCLE.length];
    return record;
  });
}

/** Those records as the JSON envelope a representative prompt batch is. */
export function jsonEnvelope(records, { sequence = 3 } = {}) {
  return `${JSON.stringify({
    schema_version: "1.0",
    kind: "wawalu.integration.query-sample",
    export_id: "3f2b91c4-0a7e-4d51-8b62-6c9d0e4a1b73",
    snapshot: {
      source_instance_id: "psn_gateway_fixture_0001",
      sequence,
      generated_at: "2026-06-30T00:00:00Z",
      bucket_granularity: "day",
      completeness: "complete",
      omitted_record_count: 0,
      issues: [],
    },
    privacy: {
      classification_site: "browser-tab",
      prompt_text_retained: false,
      direct_identifiers_included: false,
    },
    records,
  }, null, 2)}\n`;
}

/** The same records as the delimited export a gateway or proxy log is. */
export function delimitedLog(records) {
  const columns = ["org_unit_id", "query_date", "model_raw", "input_tokens", "output_tokens",
    records.some((record) => record.prompt_excerpt) ? "prompt_excerpt" : "category"];
  const cell = (value) => {
    const text = String(value ?? "");
    return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
  };
  return [columns.join(","),
    ...records.map((record) => columns.map((column) => cell(record[column])).join(",")),
  ].join("\n");
}

/**
 * The fixture table.
 *
 * `expect` is the whole point: it states what the scorer must conclude, in the
 * scorer's own vocabulary, before anyone runs it. `gradedUnits` is how many units
 * publish a letter; `unclassified` is how many records the classifier declined;
 * `confidence` is the weakest-factor level; `note` is the sentence a reviewer
 * reads to know why the row is here at all.
 */
export const ORG_QUERY_SCORING_FIXTURES = Object.freeze([
  Object.freeze({
    id: "bundled-prompt-batch",
    label: "The registry's bundled synthetic sample",
    sourceId: "representative-prompt-batch",
    bundled: "contracts/integrations/org-query-source/v1/fixtures/organizational-sample.json",
    note: "The one fixture that ships with the contract. It has to grade, or the registry "
      + "offers a source whose happy path nothing proves.",
    expect: Object.freeze({
      gradeable: true, units: 2, gradedUnits: 2, classified: 60, unclassified: 0,
      confidence: "high", declared: 60,
    }),
  }),
  Object.freeze({
    id: "gateway-log-declared-categories",
    label: "Gateway log, categories declared by the source",
    sourceId: "gateway-proxy-log",
    fileName: "gateway.csv",
    build: () => delimitedLog(fixtureRecords({ count: 60 })),
    note: "The delimited half of the contract, same expectations as the JSON half: the two "
      + "shapes are one sample seen twice and must grade identically.",
    expect: Object.freeze({
      gradeable: true, units: 2, gradedUnits: 2, classified: 60, unclassified: 0,
      confidence: "high", declared: 60,
    }),
  }),
  Object.freeze({
    id: "prompt-batch-declared-categories",
    label: "Prompt batch, categories declared by the source",
    sourceId: "representative-prompt-batch",
    fileName: "batch.json",
    build: () => jsonEnvelope(fixtureRecords({ count: 60 })),
    note: "The generated twin of the bundled fixture, so the bundled bytes are not the only "
      + "thing keeping this path alive.",
    expect: Object.freeze({
      gradeable: true, units: 2, gradedUnits: 2, classified: 60, unclassified: 0,
      confidence: "high", declared: 60,
    }),
  }),
  Object.freeze({
    id: "prompt-batch-excerpts-classified",
    label: "Prompt batch carrying excerpts the local classifier places",
    sourceId: "representative-prompt-batch",
    fileName: "excerpts.json",
    build: () => jsonEnvelope(fixtureRecords({ count: 60, excerptKey: "inefficient" })),
    note: "The redaction case with a happy ending: every record is prompt text on the way in "
      + "and a category on the way out. Nothing but the category may survive.",
    expect: Object.freeze({
      gradeable: true, units: 2, gradedUnits: 2, classified: 60, unclassified: 0,
      confidence: "high", declared: 0,
    }),
  }),
  Object.freeze({
    id: "prompt-batch-excerpts-ambiguous",
    label: "Prompt batch carrying excerpts the classifier will not place",
    sourceId: "representative-prompt-batch",
    fileName: "ambiguous.json",
    build: () => jsonEnvelope(fixtureRecords({ count: 60, excerptKey: "ambiguous" })),
    note: "Ambiguous input. The contract admits the file — every required field is there — and "
      + "the scorer must publish no letter for it, count every declined record, and say which "
      + "factor capped the confidence. A guess here would be a graded department nobody scored.",
    expect: Object.freeze({
      gradeable: false, units: 2, gradedUnits: 0, classified: 0, unclassified: 60,
      confidence: "low", declared: 0, reasonCode: "no_classified_records",
    }),
  }),
  Object.freeze({
    id: "prompt-batch-below-letter-floor",
    label: "Prompt batch with too few classified prompts per unit",
    sourceId: "representative-prompt-batch",
    fileName: "thin.json",
    build: () => jsonEnvelope(fixtureRecords({ count: 6 })),
    note: "Three prompts per unit, under the borrowed letter floor of five. No unit is graded "
      + "and the shortfall is named in whole prompts rather than implied by a small number.",
    expect: Object.freeze({
      gradeable: false, units: 2, gradedUnits: 0, classified: 6, unclassified: 0,
      confidence: "low", declared: 6, reasonCode: "no_gradeable_unit",
    }),
  }),
]);
